create policy "Authorised users can view incident media" on storage.objects for select to authenticated using (bucket_id = 'incident-media' and (storage.foldername(name))[1] ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' and exists (select 1 from public.incidents i where i.id = ((storage.foldername(name))[1])::uuid and (i.submitted_by = (select auth.uid()) or i.reporter_id = (select auth.uid()) or i.assigned_to = (select auth.uid()) or public.is_super_admin((select auth.uid())) or (public.is_campus_admin((select auth.uid())) and i.campus = public.get_user_campus((select auth.uid()))))));